fn is_even_at_index_even(lst: &Vec<i32>) -> bool {
    for (i, &v) in lst.iter().enumerate() {
        // If the index is even but the value is odd, return false
        if i % 2 == 0 && v % 2 != 0 {
            return false;
        }
    }
    // All even indices held even values
    true
}

